<?php

$lesson = fn (string $title, string $summary, string $code, string $task, array $options, int $answer, string $why) => compact('title','summary','code','task','options','answer','why');

return [
 $lesson('What is Laravel?','Laravel is a PHP framework for building maintainable web applications and APIs with routing, MVC, Eloquent, authentication, queues, cache, scheduling and testing.',"php artisan make:controller JobController\nphp artisan make:model Job -m\nphp artisan route:list",'Create a Job model with a migration and confirm the generated files.', ['A JavaScript library','A PHP web framework','A database server','A CSS framework'],1,'Laravel is an application framework written in PHP.'),
 $lesson('Laravel MVC Architecture','A route receives the request, a controller coordinates the use case, a model represents data, and a Blade view or JSON resource produces the response.',"Route::get('/jobs', [JobController::class, 'index']);\n\npublic function index() {\n    return view('jobs.index', [\n        'jobs' => Job::latest()->paginate(20),\n    ]);\n}",'Trace GET /jobs from routes/web.php to the controller, model query, and Blade view.', ['View → Route → Model','Browser → Route → Controller → Model → View','Model → Browser → Route','Controller → CSS → Database'],1,'That sequence keeps HTTP coordination, data, and presentation separated.'),
 $lesson('What is a .blade.php file?','Blade is Laravel’s server-side templating engine. It supports escaped output, layouts, components, conditions and loops inside resources/views.',"@extends('layouts.app')\n@section('content')\n  <h1>{{ \$user->name }}</h1>\n  @if(\$user->isAdmin()) <p>Admin</p> @endif\n@endsection",'Create resources/views/jobs/index.blade.php and render three job titles with @foreach.', ['A migration','A queue worker','A Blade view template','A database model'],2,'Blade files describe the HTML presentation layer.'),
 $lesson('Escaped and raw Blade output','Double braces escape HTML and protect against XSS. Raw braces output HTML and must only receive trusted, sanitized content.',"{{ \$candidateName }}\n{!! \$trustedSanitizedHtml !!}", 'Render <script>alert(1)</script> with both forms and observe why escaped output is safer.', ['Both always escape','{!! !!} escapes but {{ }} does not','{{ }} escapes; {!! !!} renders raw HTML','Neither can render variables'],2,'Laravel escapes double-brace output by default.'),
 $lesson('Routing in Laravel','Routes map an HTTP method and URI to a controller action. Named routes prevent URLs from being hardcoded throughout views.',"Route::get('/jobs', [JobController::class, 'index'])->name('jobs.index');\nRoute::post('/jobs', [JobController::class, 'store'])->name('jobs.store');",'Add a named GET route and generate its URL with route().', ['Routes create database tables','Routes connect requests to application actions','Routes compile CSS','Routes send queue jobs only'],1,'Routing is the entry map for HTTP requests.'),
 $lesson('web.php versus api.php','Web routes normally use sessions, cookies and CSRF protection. API routes are generally stateless, JSON-oriented and token authenticated.',"// routes/web.php\nRoute::get('/dashboard', DashboardController::class);\n\n// routes/api.php\nRoute::get('/jobs', [JobController::class, 'index']);",'Place a browser form route in web.php and a JSON listing endpoint in api.php.', ['Both files are identical','web.php is stateful; api.php is generally stateless','api.php renders only Blade','web.php cannot use controllers'],1,'Their middleware stacks target different kinds of clients.'),
 $lesson('Creating Controllers','Controllers coordinate HTTP input and responses. Resource controllers provide conventional CRUD action names.',"php artisan make:controller UserController\nphp artisan make:controller JobController --resource\nphp artisan make:controller Api/JobController --api",'Generate an API controller and inspect its actions.', ['make:model','make:controller','make:view','make:route'],1,'The Artisan make:controller command generates controllers.'),
 $lesson('Building a Laravel API','A production API separates routing, validation, business logic, persistence and response transformation.',"public function index(): JsonResponse\n{\n    return response()->json([\n        'success' => true,\n        'data' => Job::active()->paginate(20),\n    ]);\n}",'Build GET /api/jobs returning a paginated JSON response instead of Job::all().', ['Return every row with all columns','Route → Form Request → Service → Model → Resource','Put SQL in the Blade file','Use GET to create records'],1,'The layered flow is testable and prevents controllers becoming business-logic containers.'),
 $lesson('REST API Methods','REST uses resource-oriented URLs and HTTP methods: GET reads, POST creates, PUT replaces, PATCH partially updates and DELETE removes.',"GET /api/jobs\nPOST /api/jobs\nGET /api/jobs/42\nPATCH /api/jobs/42\nDELETE /api/jobs/42",'Design the five core endpoints for a companies resource.', ['PATCH fetches data','POST deletes data','GET reads and POST creates','DELETE partially updates'],2,'HTTP methods communicate the intended resource operation.'),
 $lesson('Testing APIs with Postman','Test headers, authentication, request JSON, response status, validation errors and resulting database changes—not only the happy path.',"POST /api/jobs\nAccept: application/json\nAuthorization: Bearer TOKEN\nContent-Type: application/json\n\n{\"title\":\"Laravel Developer\",\"experience\":5}",'Test valid input, missing title, invalid token and duplicate submission.', ['Only inspect response color','Check status, JSON, validation, auth and database effects','Never test errors','Use a browser address bar for POST'],1,'A complete API test verifies behavior and side effects.'),
 $lesson('Middleware','Middleware surrounds a request to authenticate, authorize, throttle, log or modify it before/after the controller runs.',"public function handle(\$request, Closure \$next)\n{\n    abort_unless(auth()->check(), 401);\n    return \$next(\$request);\n}",'Sketch where auth and role middleware sit in the request pipeline.', ['It creates migrations','It filters HTTP requests','It replaces models','It builds CSS'],1,'Middleware is the request pipeline’s reusable filtering layer.'),
 $lesson('Creating Role Middleware','Parameterized middleware can enforce a reusable role rule before protected controller actions execute.',"php artisan make:middleware CheckRole\n\nRoute::middleware('role:admin')->group(function () {\n    Route::get('/admin', AdminController::class);\n});",'Protect an employer dashboard so only role_code 0 can enter.', ['Check permissions in CSS','Use route middleware','Expose the page and hide its link','Store authorization in JavaScript'],1,'Server-side middleware blocks unauthorized requests even when URLs are entered directly.'),
 $lesson('Authentication','Authentication verifies identity through credentials, sessions or tokens.',"if (Auth::attempt(\$request->only('email','password'))) {\n    \$request->session()->regenerate();\n    return redirect()->intended('/dashboard');\n}",'Implement a failed-login response without revealing whether the email exists.', ['Who are you?','What can you edit?','Which CSS loads?','Which table migrates?'],0,'Authentication answers who the requester is.'),
 $lesson('Authorization','Authorization decides whether an authenticated user may perform a specific action through policies, gates or middleware.',"public function update(User \$user, Job \$job): bool\n{\n    return \$job->employer_id === \$user->id;\n}",'Write a policy rule preventing one recruiter from editing another recruiter’s job.', ['Password hashing','Permission checking','User registration','Session storage'],1,'Authorization is permission evaluation after identity is known.'),
 $lesson('Authentication versus Authorization','Authentication establishes identity; authorization evaluates permissions for that identity.',"Route::middleware(['auth','can:update,job'])\n    ->put('/jobs/{job}', [JobController::class,'update']);",'Identify which part is authentication and which is authorization in the route.', ['They are the same','Authentication is identity; authorization is permission','Authorization logs in users','Authentication defines roles'],1,'Login and access control solve different security questions.'),
 $lesson('Sessions','Sessions store temporary server-side, user-specific state while the browser holds a session identifier.',"session(['selected_company' => 42]);\n\$companyId = session('selected_company');\nreturn back()->with('status', 'Saved');",'Store a preferred job location and display a one-time flash message.', ['Permanent public storage','Temporary user-specific state','A search index','A queue broker'],1,'Sessions persist state across browser requests.'),
 $lesson('Session versus Token','Session authentication suits server-rendered web apps; tokens suit APIs, mobile apps and separate frontends.',"// Session cookie: browser sends session ID\n// Token: Authorization: Bearer <token>", 'Choose an auth mechanism for Blade dashboard and another for a mobile client.', ['Sessions are always stateless','Tokens require server-rendered Blade','Sessions suit web; tokens suit API clients','They must always be used together'],2,'The client architecture determines the appropriate mechanism.'),
 $lesson('Laravel Sanctum','Sanctum supports SPA cookie authentication and personal API tokens for mobile or third-party clients.',"\$token = \$user->createToken('mobile-app')->plainTextToken;\n\nRoute::middleware('auth:sanctum')->get('/profile', fn () => auth()->user());",'Issue a test token and call a protected endpoint with a Bearer header.', ['Database migrations only','API and SPA authentication','PDF generation','CSS compilation'],1,'Sanctum is Laravel’s lightweight API authentication package.'),
 $lesson('CSRF Protection','CSRF protection prevents another site from submitting a state-changing request using a victim’s authenticated browser session.',"<form method=\"POST\" action=\"/jobs\">\n    @csrf\n    <!-- fields -->\n</form>",'Remove @csrf from a local POST form, observe the 419 response, then restore it.', ['Cross-Site Request Forgery','Cached Server Response Format','Controller Service Route Flow','Client Session Refresh'],0,'The token proves the form originated from the trusted application.'),
 $lesson('Eloquent ORM','Eloquent maps database records and relationships to PHP model objects and provides expressive querying.',"\$jobs = Job::query()\n    ->where('status','published')\n    ->with('company')\n    ->paginate(20);",'Replace an all-record query with a filtered, eager-loaded, paginated query.', ['A template engine','An ORM','A cache server','A queue worker'],1,'Eloquent is Laravel’s object-relational mapper.'),
 $lesson('Migrations','Migrations provide version-controlled, repeatable database schema changes.',"php artisan make:migration create_jobs_table\nphp artisan migrate\nphp artisan migrate:rollback --step=1",'Create a jobs table migration with title, status, published_at and indexes.', ['Schema version control','Fake-data generation','Email delivery','Frontend routing'],0,'Migrations describe how database structure changes over time.'),
 $lesson('Adding a Column Safely','Use Schema::table in a new migration instead of editing an already-deployed migration.',"Schema::table('users', function (Blueprint \$table) {\n    \$table->string('phone')->nullable()->after('email');\n});",'Add nullable phone and write a matching down() operation.', ['Edit production manually','Create a new migration using Schema::table','Delete the users table','Change the model only'],1,'New migrations keep every environment’s schema history consistent.'),
 $lesson('Rolling Back Migrations','Rollback reverses the latest migration batch; --step limits how many migrations are reversed.',"php artisan migrate:rollback --step=1\nphp artisan migrate:status",'Run migration status before and after rolling back one disposable local migration.', ['migrate:fresh','migrate:rollback --step=1','db:seed','route:clear'],1,'The rollback command executes the migration’s down() method.'),
 $lesson('Seeders','Seeders insert controlled initial or development data such as roles, technologies and supported companies.',"php artisan make:seeder TechnologySeeder\nphp artisan db:seed --class=TechnologySeeder",'Create an idempotent seeder using updateOrCreate for five technologies.', ['Insert initial/test data','Change table columns','Handle requests','Compile views'],0,'Seeders populate data; migrations define structure.'),
 $lesson('Factories','Factories generate realistic model data for automated tests and local development.',"User::factory()->count(100)->create();\nJob::factory()->for(\$company)->count(25)->create();",'Use a factory in a test to create an employer, company and three jobs.', ['Production secrets','Fake model data','Route definitions','Blade components'],1,'Factories efficiently create test fixtures.'),
 $lesson('Mass Assignment and Fillable','Mass assignment fills several attributes together. Protect sensitive columns with $fillable or $guarded and persist only validated input.',"protected \$fillable = ['name','email','phone'];\nUser::create(\$request->validated());",'Submit an unexpected role_code and confirm it is not saved.', ['Trust $request->all()','Use an allow-list and validated data','Disable protection','Trust hidden fields'],1,'Allow-listed validated input prevents unauthorized column changes.'),
 $lesson('Form Requests','Form Requests move validation and authorization into reusable request classes.',"php artisan make:request StoreJobRequest\npublic function rules(): array { return ['title'=>['required','max:150']]; }",'Create StoreJobRequest and type-hint it in store().', ['Blade component','Validation request class','Queue worker','Database index'],1,'Form Requests keep controllers small and rules reusable.'),
 $lesson('Validated Input','validated() returns only fields accepted by a Form Request.',"\$job = Job::create(\$request->validated());",'Prove an unvalidated is_featured field is discarded.', ['$request->all()','$request->server()','$request->validated()','$request->query()'],2,'validated() is the safe boundary between input and persistence.'),
 $lesson('Custom Validation Rules','Closure rules or Rule classes express business constraints beyond built-in validation.',"'deadline'=>[function (\$attribute, \$value, \$fail) {\n if (now()->parse(\$value)->isPast()) \$fail('Must be future.');\n}]",'Reject a job deadline in the past.', ['Use CSS','Use a closure or Rule class','Skip validation','Insert first'],1,'Custom rules make domain validation explicit and testable.'),
 $lesson('Service Layer','Services contain business workflows that should not live in HTTP controllers.',"final class PublishJobService {\n public function publish(Job \$job): Job {\n  \$job->update(['status'=>'published']); return \$job;\n }\n}",'Move publishing logic into a tested service.', ['HTML styling','Business use-case logic','Routes only','Credentials'],1,'Services isolate application behavior from HTTP delivery.'),
 $lesson('Dependency Injection','Dependency injection supplies collaborators through constructors or methods instead of constructing them internally.',"public function __construct(private PublishJobService \$publisher) {}",'Inject a mailer interface and fake it in a test.', ['Use new everywhere','Receive dependencies explicitly','Use globals','Use sessions'],1,'Injection makes coupling visible and implementations replaceable.'),
 $lesson('Service Container','Laravel’s service container resolves dependencies and interface bindings.',"\$this->app->bind(JobRepository::class, EloquentJobRepository::class);",'Replace a repository binding with a fake in a test.', ['Database table','Dependency resolver','CSS container','Browser cache'],1,'The container builds object graphs and resolves abstractions.'),
 $lesson('Service Providers','Service providers register bindings and bootstrap application services.',"final class JobServiceProvider extends ServiceProvider {\n public function register(): void { /* bindings */ }\n}",'Create a provider for the job module.', ['Register and bootstrap services','Render every view','Store resumes','Replace migrations'],0,'Providers are Laravel’s application bootstrapping mechanism.'),
 $lesson('register() versus boot()','register() defines bindings; boot() performs setup after providers are registered.',"public function register(): void { /* bind */ }\npublic function boot(): void { Job::observe(JobObserver::class); }",'Put a binding and observer in their correct methods.', ['Identical methods','register binds; boot performs setup','boot runs first','register renders views'],1,'Correct phases prevent services being resolved too early.'),
 $lesson('Repository Pattern','A repository hides persistence details behind a domain-focused interface when the boundary is useful.',"interface JobRepository { public function published(array \$filters); }",'Inject a published-job repository into a search service.', ['Always mandatory','Data-access abstraction','Frontend store','Queue driver'],1,'Repositories help at real persistence boundaries but can add needless ceremony.'),
 $lesson('Eloquent Relationships','Relationships define model associations such as a company having many jobs.',"public function jobs(): HasMany { return \$this->hasMany(Job::class); }",'Define Company hasMany Jobs and Job belongsTo Company.', ['CSS selector','Model association','Route group','Cache tag'],1,'Relationships provide expressive associated-data queries.'),
 $lesson('Eager Loading','Eager loading fetches related records in a small, predictable number of queries.',"\$jobs = Job::with(['company:id,name','skills:id,name'])->paginate(20);",'Compare query counts with and without with(company).', ['Use with()','Call all() repeatedly','Query in Blade','Disable relations'],0,'with() batches relation queries.'),
 $lesson('N+1 Query Problem','N+1 is one list query followed by another query for every item’s relationship.',"\$jobs = Job::with('company')->get();\nforeach (\$jobs as \$job) echo \$job->company->name;",'Profile the queries for 100 jobs.', ['Missing migration','One query plus N relation queries','Cache collision','Queue retry'],1,'Eager loading prevents repeated per-row queries.'),
 $lesson('Lazy versus Eager Loading','Lazy loading queries when accessed; eager loading fetches known relations up front. load() works after retrieval.',"\$job->load(['company','skills']);\n\$jobs = Job::with('company')->get();",'Use with() for a list and loadMissing() for an optional relation.', ['Lazy is always faster','Eager load known relations','load deletes data','with caches forever'],1,'Choose based on which relations the response will use.'),
 $lesson('Eloquent versus Query Builder','Eloquent provides models and relationships; Query Builder is useful for aggregates and bulk operations.',"\$jobs = Job::published()->paginate();\n\$counts = DB::table('jobs')->selectRaw('company_id,count(*) total')->groupBy('company_id')->get();",'Use each approach for a suitable job-portal query.', ['Unrelated databases','Models versus lower-level queries','Builder cannot filter','Eloquent cannot paginate'],1,'Match the abstraction to domain models or efficient data operations.'),
 $lesson('Accessors and Mutators','Accessors transform values when read; mutators normalize values when written.',"return Attribute::make(get: fn (\$v) => str(\$v)->title(), set: fn (\$v) => trim(\$v));",'Normalize and format a title, then test both directions.', ['Change URLs','Transform model attributes','Dispatch queues','Create indexes'],1,'Attribute transforms centralize representation rules.'),
 $lesson('Local Query Scopes','Local scopes package reusable query constraints while remaining composable.',"public function scopePublished(Builder \$query): void { \$query->where('status','published'); }",'Create and combine published() and remote() scopes.', ['Reusable model query','Global middleware','Blade slot','Queue batch'],0,'Scopes remove duplicated query conditions.'),
 $lesson('Global Scopes','Global scopes automatically constrain every query for a model and should be used carefully.',"static::addGlobalScope('active', fn (Builder \$q) => \$q->where('status','published'));",'Add a tenant scope and explicitly bypass it for an authorized report.', ['One query only','Automatic model constraint','JavaScript filter','Rollback'],1,'Global scopes are implicit and need controlled escape paths.'),
 $lesson('Soft Deletes','Soft deletes set deleted_at, preserving rows for recovery while hiding them from normal queries.',"use SoftDeletes;\n\$job->delete();\n\$job->restore();",'Delete, hide, restore and then permanently delete a test job.', ['Always erased','Marked with deleted_at','Files only','Disables timestamps'],1,'Soft deletion supports recovery and audit-friendly workflows.'),
 $lesson('Events and Listeners','Events announce occurrences; listeners independently handle indexing, audit logging or notifications.',"JobPublished::dispatch(\$job);\nfinal class UpdateSearchIndex { public function handle(JobPublished \$event): void {} }",'Add separate indexing and notification listeners.', ['Couple side effects','Separate occurrence from reactions','Replace validation','Store passwords'],1,'Events reduce coupling between workflows and side effects.'),
 $lesson('Dispatching Events Safely','Dispatch after a database transaction commits so listeners never observe rolled-back data.',"DB::transaction(function () use (\$job) {\n \$job->update(['status'=>'published']);\n JobPublished::dispatch(\$job)->afterCommit();\n});",'Verify a listener runs only after commit.', ['Before validation','After committed state change','Inside Blade','During migration'],1,'After-commit delivery keeps side effects consistent with stored state.'),
 $lesson('Queues, Jobs and Workers','Queues move slow email, resume parsing and indexing work outside the web request; workers process retries and failures.',"ProcessResume::dispatch(\$resume);\nphp artisan queue:work --tries=3 --backoff=10",'Create a queued resume parser and test with Queue::fake().', ['Run on every refresh','Dispatch and process with a worker','Use browser memory','Disable failures'],1,'Queues keep requests responsive and provide controlled retry behavior.'),
];
